cd __REPO__ && python3 -c "
import json, collections
types = collections.Counter(); hyps=set(); links=[]
for line in open('.theta/notebook.jsonl'):
    e=json.loads(line); types[e['type']]+=1
    if e['type']=='hypothesis': hyps.add(e['id'])
    for ev in e.get('evidence') or []:
        if 'supports' in ev: links.append((e['id'], ev['supports']))
print(dict(types)); print('links:', links)
bad=[l for l in links if l[1] not in hyps]; print('unresolved:', bad or 'none')
import os
print('snapshots:', len(os.listdir('.theta/evidence')))
"
